import{preparerExercice}from"./chunk-Y4MCCTGS.js";import{fiche,minutes,nombre}from"./chunk-TEUV4QWW.js";import{maths}from"./chunk-IU7R2CUX.js";import{chapitreComplet}from"./chunk-CVSPVNUI.js";import{RACINE}from"./chunk-MENTKLMX.js";import{echap}from"./chunk-CG5YCEWP.js";var pages=new Map;function lirePage(chemin){return pages.has(chemin)||pages.set(chemin,fetch(RACINE+chemin).then(r=>{if(!r.ok)throw new Error("Page "+chemin+" : "+r.status);return r.text()}).then(t=>new DOMParser().parseFromString(t,"text/html"))),pages.get(chemin)}function adresse(id){let f=fiche(id);if(f)return{page:f.page,ancre:f.ancre,fiche:f};let[ch,nom]=String(id).split("/"),c=chapitreComplet(ch);return c&&c.fichier&&nom?{page:c.fichier,ancre:"ex-"+nom,fiche:null}:null}function rebaser(el,chemin){let base=new URL(RACINE+chemin,location.href);el.querySelectorAll("[href],[src]").forEach(n=>["href","src"].forEach(at=>{let v=n.getAttribute(at);v==null||/^(data:|https?:|mailto:|javascript:)/i.test(v)||n.setAttribute(at,new URL(v,base).href)}))}async function chargerFiche(id){let o=adresse(id);if(!o)return null;try{let a=(await lirePage(o.page)).getElementById(o.ancre);if(!a||!a.matches("article.exercice"))return null;let c=document.importNode(a,!0);return rebaser(c,o.page),c.id="f-"+id.replace("/","--"),c.dataset.fiche=id,{id,article:c,fiche:o.fiche||{id,titre:a.dataset.titre||"",duree:+a.dataset.duree||0,difficulte:+a.dataset.niveau||0,calculatrice:a.dataset.calculatrice==="oui"},page:o.page}}catch(e){return console.warn(e),null}}function chargerTout(ids){return Promise.all(ids.map(chargerFiche))}function meta(f,points){let l=[];return f&&f.duree&&l.push("environ "+minutes(f.duree)),f&&l.push(f.calculatrice?"calculatrice autorisée":"sans calculatrice"),points!=null&&l.push("<b>"+nombre(points)+" point"+(points>1?"s":"")+"</b>"),'<p class="fiche-meta discret">'+l.join(" · ")+"</p>"}function preparer(it,numero,points){let a=it.article;return preparerExercice(a,numero),a.querySelector(":scope > header").insertAdjacentHTML("afterend",meta(it.fiche,points)),a}async function habiller(el){maths(el);try{el.querySelector("figure.graphe")&&(await import("./graphe-EWREROES.js")).init(el),el.querySelector(".tuteur")&&(await import("./tuteur-6EEGKNTS.js")).init(el)}catch(e){console.warn(e)}}function introuvable(id,numero){return'<article class="exercice introuvable"><header><span class="num-ex">Exercice '+numero+"</span></header><p>Cet exercice est introuvable : il a peut-être été retiré de la banque, ou le lien est abîmé (<code>"+echap(id)+"</code>).</p></article>"}async function apercu(id,cont){cont.innerHTML='<p class="discret">Lecture de la fiche dans son chapitre…</p>';let it=await chargerFiche(id);return it?(cont.innerHTML="",cont.appendChild(preparer(it,1)),await habiller(cont),it):(cont.innerHTML=introuvable(id,1),null)}export{chargerTout,preparer,habiller,introuvable,apercu};
